package com.rulecraft.decisionops.deployment;

import com.rulecraft.decisionops.audit.AuditService;import com.rulecraft.decisionops.catalog.CatalogService;import com.rulecraft.decisionops.catalog.domain.DecisionServiceStatus;import com.rulecraft.decisionops.catalog.persistence.DecisionServiceRepository;import com.rulecraft.decisionops.deployment.domain.*;import com.rulecraft.decisionops.deployment.persistence.*;import com.rulecraft.decisionops.identity.security.RuleCraftPrincipal;import com.rulecraft.decisionops.platform.web.DomainProblemException;import com.rulecraft.decisionops.projects.ProjectAccessPolicy;import com.rulecraft.decisionops.versions.domain.*;import com.rulecraft.decisionops.versions.persistence.DecisionVersionRepository;import com.rulecraft.decisionops.workflow.persistence.DecisionPromotionRepository;import java.time.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import tools.jackson.databind.JsonNode;

@Service
public class RuntimeDeploymentService {
    private final RuntimeEnvironmentRepository environments;private final RuntimeDeploymentRepository deployments;private final RuntimeDeploymentEventRepository events;private final DecisionPromotionRepository promotions;private final DecisionVersionRepository versions;private final DecisionServiceRepository services;private final ProjectAccessPolicy access;private final CatalogService catalog;private final CapturedDecisionRuntime runtime;private final AuditService audit;private final Clock clock;
    public RuntimeDeploymentService(RuntimeEnvironmentRepository environments,RuntimeDeploymentRepository deployments,RuntimeDeploymentEventRepository events,DecisionPromotionRepository promotions,DecisionVersionRepository versions,DecisionServiceRepository services,ProjectAccessPolicy access,CatalogService catalog,CapturedDecisionRuntime runtime,AuditService audit,Clock clock){this.environments=environments;this.deployments=deployments;this.events=events;this.promotions=promotions;this.versions=versions;this.services=services;this.access=access;this.catalog=catalog;this.runtime=runtime;this.audit=audit;this.clock=clock;}
    @Transactional(readOnly=true)public SandboxView sandbox(RuleCraftPrincipal actor,UUID projectId,UUID serviceId){access.requireVisible(actor,projectId);catalog.getService(actor,projectId,serviceId);var environment=environments.findByServiceIdAndTenantIdAndProjectId(serviceId,actor.tenantId(),projectId);var promotion=promotions.findByServiceIdAndTenantIdAndProjectId(serviceId,actor.tenantId(),projectId);var promoted=promotion.flatMap(value->versions.findByIdAndDecisionServiceIdAndTenantIdAndProjectId(value.getDecisionVersionId(),serviceId,actor.tenantId(),projectId)).map(this::version).orElse(null);if(environment.isEmpty())return new SandboxView(null,List.of(),promoted,promotion.map(value->value.getRevision()).orElse(null),access.roleFor(actor,projectId));var value=environment.get();return new SandboxView(environment(value),deployments.findTop100ByEnvironmentIdOrderBySequenceNumberDesc(value.getId()).stream().map(this::view).toList(),promoted,promotion.map(item->item.getRevision()).orElse(null),access.roleFor(actor,projectId));}
    @Transactional public DeploymentView deploy(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,DeployCommand command){access.requirePromote(actor,projectId);if(command==null||command.clientRequestId()==null)bad("RC-DEPLOY-REQUEST-ID","Provide a client request ID so deployment retries remain idempotent.");var retry=deployments.findByTenantIdAndServiceIdAndClientRequestId(actor.tenantId(),serviceId,command.clientRequestId());if(retry.isPresent())return view(retry.get());var locked=services.lockForVersionCapture(serviceId,actor.tenantId(),projectId).orElseThrow(this::notFound);if(locked.getStatus()!=DecisionServiceStatus.ACTIVE)conflict("RC-DEPLOY-SERVICE-ARCHIVED","Restore the decision service before activating a runtime artifact.");var promotion=promotions.findByServiceIdAndTenantIdAndProjectId(serviceId,actor.tenantId(),projectId).orElseThrow(()->problem(HttpStatus.CONFLICT,"RC-DEPLOY-NO-PROMOTION","Promote an approved decision version before deploying it."));if(command.expectedPromotionRevision()==null||command.expectedPromotionRevision()!=promotion.getRevision())conflict("RC-DEPLOY-PROMOTION-STALE","The promoted baseline changed. Refresh the runtime sandbox before deploying.");if(command.decisionVersionId()==null||!command.decisionVersionId().equals(promotion.getDecisionVersionId()))conflict("RC-DEPLOY-PROMOTION-MISMATCH","Only the current promoted decision version can be deployed.");var version=versions.findByIdAndDecisionServiceIdAndTenantIdAndProjectId(command.decisionVersionId(),serviceId,actor.tenantId(),projectId).orElseThrow(()->problem(HttpStatus.NOT_FOUND,"RC-DEPLOY-VERSION-NOT-FOUND","The promoted decision version was not found."));if(version.getValidationStatus()!=VersionValidationStatus.VALID)conflict("RC-DEPLOY-VERSION-INVALID","Only a valid promoted decision version can be deployed.");var now=Instant.now(clock);var environment=environments.lockByService(serviceId,actor.tenantId(),projectId).orElseGet(()->environments.saveAndFlush(new RuntimeEnvironment(actor.tenantId(),projectId,serviceId,now)));var count=deployments.countByEnvironmentId(environment.getId());if(count>=10000)bad("RC-DEPLOY-LIMIT","The local sandbox can retain at most 10000 deployment attempts.");var value=deployments.saveAndFlush(new RuntimeDeployment(actor.tenantId(),projectId,serviceId,environment.getId(),version.getId(),promotion.getRequestId(),command.clientRequestId(),(int)count+1,version.getSnapshotJson(),version.getFingerprint(),actor.userId(),actor.displayName(),now));event(actor,value,"CREATED",null,RuntimeDeploymentState.CREATED,"Immutable artifact accepted",now);var before=value.transition(RuntimeDeploymentState.VALIDATING,now);event(actor,value,"VALIDATION_STARTED",before,RuntimeDeploymentState.VALIDATING,null,now);try{runtime.validateArtifact(runtime.parse(value.getArtifactJson()));}catch(DomainProblemException failure){value.fail(failure.getCode(),safe(failure.getMessage()),now);event(actor,value,"VALIDATION_FAILED",RuntimeDeploymentState.VALIDATING,RuntimeDeploymentState.FAILED,safe(failure.getMessage()),now);deployments.save(value);audit.record(actor.tenantId(),actor.userId(),"RUNTIME_DEPLOYMENT_FAILED","RUNTIME_DEPLOYMENT",value.getId(),Map.of("serviceId",serviceId,"versionId",version.getId(),"code",failure.getCode()));return view(value);}if(environment.getActiveDeploymentId()!=null){var active=deployments.findByIdAndServiceIdAndTenantIdAndProjectId(environment.getActiveDeploymentId(),serviceId,actor.tenantId(),projectId).orElseThrow(()->problem(HttpStatus.CONFLICT,"RC-DEPLOY-ACTIVE-MISSING","The sandbox active pointer is inconsistent. Repair it before deploying."));if(active.getState()!=RuntimeDeploymentState.ACTIVE)conflict("RC-DEPLOY-ACTIVE-STATE","The sandbox active pointer does not reference an active deployment.");var old=active.transition(RuntimeDeploymentState.RETIRED,now);event(actor,active,"SUPERSEDED",old,RuntimeDeploymentState.RETIRED,"Replaced by deployment #"+value.getSequenceNumber(),now);deployments.save(active);}before=value.transition(RuntimeDeploymentState.ACTIVE,now);environment.activate(value.getId(),now);event(actor,value,"ACTIVATED",before,RuntimeDeploymentState.ACTIVE,"Local sandbox activation",now);deployments.save(value);environments.save(environment);audit.record(actor.tenantId(),actor.userId(),"RUNTIME_DEPLOYMENT_ACTIVATED","RUNTIME_DEPLOYMENT",value.getId(),Map.of("serviceId",serviceId,"versionId",version.getId(),"sequence",value.getSequenceNumber()));return view(value);}
    @Transactional public DeploymentView retire(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID deploymentId,StateCommand command){access.requirePromote(actor,projectId);var environment=lockEnvironment(actor,projectId,serviceId);var value=require(actor,projectId,serviceId,deploymentId);if(value.getState()==RuntimeDeploymentState.RETIRED&&environment.getActiveDeploymentId()==null)return view(value);expected(environment,command);if(!Objects.equals(environment.getActiveDeploymentId(),deploymentId)||value.getState()!=RuntimeDeploymentState.ACTIVE)conflict("RC-DEPLOY-NOT-ACTIVE","Only the current active deployment can be retired.");var now=Instant.now(clock);var before=value.transition(RuntimeDeploymentState.RETIRED,now);environment.clear(now);event(actor,value,"RETIRED",before,RuntimeDeploymentState.RETIRED,note(command),now);deployments.save(value);environments.save(environment);audit.record(actor.tenantId(),actor.userId(),"RUNTIME_DEPLOYMENT_RETIRED","RUNTIME_DEPLOYMENT",value.getId(),Map.of("serviceId",serviceId));return view(value);}
    @Transactional public DeploymentView rollback(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID targetId,StateCommand command){access.requirePromote(actor,projectId);var environment=lockEnvironment(actor,projectId,serviceId);var target=require(actor,projectId,serviceId,targetId);if(Objects.equals(environment.getActiveDeploymentId(),targetId)&&target.getState()==RuntimeDeploymentState.ACTIVE)return view(target);expected(environment,command);if(environment.getActiveDeploymentId()==null)conflict("RC-DEPLOY-ROLLBACK-NO-ACTIVE","Rollback requires a current active deployment.");if(target.getState()!=RuntimeDeploymentState.RETIRED)conflict("RC-DEPLOY-ROLLBACK-MISMATCH","Rollback can reactivate only a retired successful deployment from this sandbox.");runtime.validateArtifact(runtime.parse(target.getArtifactJson()));var active=require(actor,projectId,serviceId,environment.getActiveDeploymentId());if(active.getId().equals(target.getId()))conflict("RC-DEPLOY-ROLLBACK-SAME","Choose an earlier retired deployment to roll back to.");var now=Instant.now(clock);var from=active.transition(RuntimeDeploymentState.ROLLED_BACK,now);event(actor,active,"ROLLED_BACK",from,RuntimeDeploymentState.ROLLED_BACK,"Replaced by rollback to deployment #"+target.getSequenceNumber(),now);from=target.transition(RuntimeDeploymentState.ACTIVE,now);event(actor,target,"REACTIVATED",from,RuntimeDeploymentState.ACTIVE,note(command),now);environment.activate(target.getId(),now);deployments.save(active);deployments.save(target);environments.save(environment);audit.record(actor.tenantId(),actor.userId(),"RUNTIME_DEPLOYMENT_ROLLED_BACK","RUNTIME_DEPLOYMENT",target.getId(),Map.of("serviceId",serviceId,"replacedDeploymentId",active.getId()));return view(target);}
    @Transactional(readOnly=true)public DeploymentDetail detail(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID deploymentId){access.requireVisible(actor,projectId);catalog.getService(actor,projectId,serviceId);var value=require(actor,projectId,serviceId,deploymentId);return new DeploymentDetail(view(value),events.findAllByDeploymentIdOrderByCreatedAtAsc(value.getId()).stream().map(this::eventView).toList());}
    @Transactional(readOnly=true)public EvaluationView evaluate(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,EvaluationCommand command){access.requireVisible(actor,projectId);catalog.getService(actor,projectId,serviceId);var environment=environments.findByServiceIdAndTenantIdAndProjectId(serviceId,actor.tenantId(),projectId).orElseThrow(()->problem(HttpStatus.CONFLICT,"RC-DEPLOY-NO-ENVIRONMENT","Deploy a promoted version to the local sandbox before evaluating it."));if(environment.getActiveDeploymentId()==null)conflict("RC-DEPLOY-NO-ACTIVE","The local sandbox has no active deployment.");var deployment=require(actor,projectId,serviceId,environment.getActiveDeploymentId());if(deployment.getState()!=RuntimeDeploymentState.ACTIVE)conflict("RC-DEPLOY-ACTIVE-STATE","The local sandbox active pointer does not reference an active deployment.");var evaluated=runtime.evaluate(deployment.getArtifactJson(),command==null?Map.of():command.inputs());var id=UUID.randomUUID();audit.record(actor.tenantId(),actor.userId(),"RUNTIME_SANDBOX_EVALUATED","RUNTIME_DEPLOYMENT",deployment.getId(),Map.of("evaluationId",id,"serviceId",serviceId,"outputs",evaluated.outputs().keySet()));return new EvaluationView(id,deployment.getId(),deployment.getDecisionVersionId(),deployment.getArtifactFingerprint(),evaluated.outputs(),evaluated.decisions());}
    private RuntimeEnvironment lockEnvironment(RuleCraftPrincipal actor,UUID projectId,UUID serviceId){services.lockForVersionCapture(serviceId,actor.tenantId(),projectId).orElseThrow(this::notFound);return environments.lockByService(serviceId,actor.tenantId(),projectId).orElseThrow(()->problem(HttpStatus.CONFLICT,"RC-DEPLOY-NO-ENVIRONMENT","The local runtime sandbox has not been initialized."));}private void expected(RuntimeEnvironment environment,StateCommand command){if(command==null||command.clientRequestId()==null)bad("RC-DEPLOY-REQUEST-ID","Provide a client request ID so action retries remain safe.");if(command.expectedEnvironmentRevision()==null||command.expectedEnvironmentRevision()!=environment.getRevision())conflict("RC-DEPLOY-STALE","The runtime sandbox changed. Refresh before retrying.");}private RuntimeDeployment require(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID id){return deployments.findByIdAndServiceIdAndTenantIdAndProjectId(id,serviceId,actor.tenantId(),projectId).orElseThrow(()->problem(HttpStatus.NOT_FOUND,"RC-DEPLOY-NOT-FOUND","Runtime deployment not found."));}private void event(RuleCraftPrincipal actor,RuntimeDeployment deployment,String type,RuntimeDeploymentState from,RuntimeDeploymentState to,String note,Instant now){events.save(new RuntimeDeploymentEvent(actor.tenantId(),deployment.getId(),type,from,to,actor.userId(),actor.displayName(),note,now));}private String safe(String value){if(value==null)return "Artifact validation failed.";return value.length()>600?value.substring(0,600):value;}private String note(StateCommand command){return command==null||command.note()==null||command.note().isBlank()?null:safe(command.note().strip());}
    private EnvironmentView environment(RuntimeEnvironment value){return new EnvironmentView(value.getId(),value.getEnvironmentKey(),value.getName(),value.getActiveDeploymentId(),value.getRevision(),value.getUpdatedAt());}private DeploymentView view(RuntimeDeployment value){var version=versions.findById(value.getDecisionVersionId()).filter(item->item.getTenantId().equals(value.getTenantId())).map(this::version).orElse(null);return new DeploymentView(value.getId(),value.getSequenceNumber(),value.getDecisionVersionId(),version==null?null:version.versionNumber(),version==null?"Unavailable version":version.label(),value.getChangeRequestId(),value.getState(),value.getArtifactFingerprint(),value.getFailureCode(),value.getFailureDetail(),value.getDeployedByName(),value.getCreatedAt(),value.getUpdatedAt(),value.getRevision());}private VersionView version(DecisionVersion value){return new VersionView(value.getId(),value.getVersionNumber(),value.getLabel(),value.getFingerprint());}private EventView eventView(RuntimeDeploymentEvent value){return new EventView(value.getId(),value.getEventType(),value.getFromState(),value.getToState(),value.getActorName(),value.getNote(),value.getCreatedAt());}private DomainProblemException notFound(){return problem(HttpStatus.NOT_FOUND,"RC-DEPLOY-SERVICE-NOT-FOUND","Decision service not found.");}private void bad(String code,String detail){throw problem(HttpStatus.BAD_REQUEST,code,detail);}private void conflict(String code,String detail){throw problem(HttpStatus.CONFLICT,code,detail);}private DomainProblemException problem(HttpStatus status,String code,String detail){return new DomainProblemException(status,code,detail);}
    public record DeployCommand(UUID clientRequestId,UUID decisionVersionId,Long expectedPromotionRevision){}public record StateCommand(UUID clientRequestId,Long expectedEnvironmentRevision,String note){}public record EvaluationCommand(Map<String,JsonNode> inputs){}public record VersionView(UUID id,int versionNumber,String label,String fingerprint){}public record EnvironmentView(UUID id,String environmentKey,String name,UUID activeDeploymentId,long revision,Instant updatedAt){}public record DeploymentView(UUID id,int sequenceNumber,UUID decisionVersionId,Integer decisionVersionNumber,String decisionVersionLabel,UUID changeRequestId,RuntimeDeploymentState state,String artifactFingerprint,String failureCode,String failureDetail,String deployedByName,Instant createdAt,Instant updatedAt,long revision){}public record EventView(UUID id,String eventType,RuntimeDeploymentState fromState,RuntimeDeploymentState toState,String actorName,String note,Instant createdAt){}public record SandboxView(EnvironmentView environment,List<DeploymentView> deployments,VersionView promotedVersion,Long promotionRevision,String accessRole){}public record DeploymentDetail(DeploymentView deployment,List<EventView> events){}public record EvaluationView(UUID evaluationId,UUID deploymentId,UUID decisionVersionId,String artifactFingerprint,Map<String,JsonNode> outputs,List<CapturedDecisionRuntime.DecisionTrace> decisions){}
}
